// src/app/models/help-content.model.ts
import { HelpSection } from '../content/view-help.content';

/** One editable help section. `bodyHtml` is DOMPurify-sanitized rich text. */
export interface EditableHelpSection {
  id: string;
  title: string;
  bodyHtml: string;
  items: { term: string; description: string; technical?: string }[];
  media: HelpMediaRef[];
}

export interface HelpMediaRef {
  imageId: number;
  caption?: string;
  type: 'image' | 'gif';
}

/** The ONC_SCHED / HELP_CONTENT dm_info payload. */
export interface StoredHelpContent {
  UPDT_DT_TM: string;
  sections: EditableHelpSection[];
}

/** One ONC_SCHED / HELP_IMAGE dm_info payload (domainId = imageId). */
export interface StoredHelpImage {
  dataUrl: string;
  mime: string;
  width: number;
  height: number;
  bytes: number;
}

/** Convert a shipped (compiled-in) section to the editable shape. */
export function toEditableSection(shipped: HelpSection): EditableHelpSection {
  return {
    id: shipped.id,
    title: shipped.title,
    bodyHtml: (shipped.body ?? []).map(p => `<p>${p}</p>`).join(''),
    items: (shipped.items ?? []).map(i => ({ ...i })),
    media: []
  };
}

/**
 * Merge policy (spec 2026-07-03): stored sections win by id in stored order;
 * shipped sections whose id is absent from stored auto-append in shipped order.
 */
export function mergeHelpSections(
  stored: EditableHelpSection[],
  shipped: HelpSection[]
): EditableHelpSection[] {
  const storedIds = new Set(stored.map(s => s.id));
  const appended = shipped.filter(s => !storedIds.has(s.id)).map(toEditableSection);
  return [...stored, ...appended];
}

/**
 * Same merge policy as `mergeHelpSections`, but for two already-editable arrays.
 * Used as a belt-and-braces safety net when the seed effect fires while the
 * editor already has local sections (should not happen once the editor is
 * gated on `loaded()`, but this guarantees the seed can never clobber
 * un-saved user work if it ever does): local sections win by id in local
 * order, and any effective section missing from local auto-appends in
 * effective order.
 */
export function mergeEditableSections(
  local: EditableHelpSection[],
  effective: EditableHelpSection[]
): EditableHelpSection[] {
  const localIds = new Set(local.map(s => s.id));
  const appended = effective.filter(s => !localIds.has(s.id));
  return [...local, ...appended];
}

/**
 * Pure comparison used by the editor's `hasUnsavedChanges` — extracted so it
 * can be unit tested without standing up the full HelpEditorComponent (whose
 * RTE child uses a real TipTap editor and is impractical to TestBed).
 *
 * Before the seed effect has copied loaded content into the local editing
 * signal, `current` is still `[]` while `baseline` already holds the shipped
 * defaults - comparing them would spuriously report unsaved changes and
 * enable Save/Discard before there is anything to edit.
 */
export function hasUnsavedHelpChanges(
  loaded: boolean,
  current: EditableHelpSection[],
  baseline: EditableHelpSection[]
): boolean {
  if (!loaded || current.length === 0) return false;
  return JSON.stringify(current) !== JSON.stringify(baseline);
}
