// src/app/services/help-content.service.ts
import { Injectable, inject, signal, computed } from '@angular/core';
import { CustomService, MPageService } from '@clinicaloffice/mpage-developer';
import { HELP_SECTIONS } from '../content/view-help.content';
import {
  EditableHelpSection, StoredHelpContent, StoredHelpImage,
  mergeHelpSections, toEditableSection
} from '../models/help-content.model';

const DMINFO_DOMAIN = 'ONC_SCHED';
const CONTENT_NAME = 'HELP_CONTENT';
const IMAGE_NAME = 'HELP_IMAGE';

/** dm_info read result shape varies: PowerChart returns { dmInfo: [{ longText }] },
 * other paths return longText/infoLongText at the top level (same chain as ConfigurationService). */
interface DmInfoReadResult {
  dmInfo?: { longText?: string }[];
  longText?: string;
  infoLongText?: string;
}

function readLongText(result: DmInfoReadResult | undefined): string | undefined {
  return result?.dmInfo?.[0]?.longText ?? result?.longText ?? result?.infoLongText;
}

@Injectable({ providedIn: 'root' })
export class HelpContentService {
  private readonly customService = inject(CustomService);
  private readonly mPage = inject(MPageService);

  private readonly _storedSections = signal<EditableHelpSection[] | null>(null);
  private readonly _loaded = signal(false);
  private loading = false;
  /** Monotonic request token — bumped on each load and on save; stale read callbacks are discarded. */
  private loadToken = 0;
  private readonly images = new Map<number, StoredHelpImage>();

  readonly storedSections = this._storedSections.asReadonly();
  readonly loaded = this._loaded.asReadonly();

  /** Stored sections (when present) merged with shipped defaults; shipped-only until loaded. */
  readonly effectiveSections = computed<EditableHelpSection[]>(() =>
    mergeHelpSections(this._storedSections() ?? [], HELP_SECTIONS));

  loadContent(): void {
    if (this._loaded() || this.loading) return;
    this.loading = true;

    // A stalled read's callback can fire long after a retry (or a save) has
    // already updated the signals; the token lets such stale responses be
    // discarded instead of regressing the baseline.
    const token = ++this.loadToken;

    const dmInfo = this.customService.emptyDmInfo;
    dmInfo.infoDomain = DMINFO_DOMAIN;
    dmInfo.infoName = CONTENT_NAME;
    dmInfo.infoDomainId = 0;

    this.customService.executeDmInfoAction('loadHelpContent', 'r', [dmInfo], () => {
      if (token !== this.loadToken) {
        this.mPage.putLog('Stale help content response ignored');
        return;
      }
      try {
        const result = this.customService.get('loadHelpContent');
        const longText = readLongText(result);
        if (longText) {
          const parsed = JSON.parse(longText) as StoredHelpContent;
          if (Array.isArray(parsed.sections)) {
            this._storedSections.set(parsed.sections);
          }
        }
      } catch {
        this.mPage.putLog('Help content record unreadable - using built-in help');
      }
      this.loading = false;
      this._loaded.set(true);
    });
  }

  /**
   * Re-invoke loadContent() after a stalled attempt (e.g. the dm_info
   * callback never fired). Resets the in-flight `loading` guard so
   * loadContent() doesn't just no-op; `_loaded` is left as-is since a prior
   * attempt may have already succeeded by the time retry is requested.
   */
  retryLoad(): void {
    this.loading = false;
    this.loadContent();
  }

  saveContent(sections: EditableHelpSection[]): void {
    // Invalidate any still-in-flight read so a late response can't
    // overwrite the freshly saved baseline.
    this.loadToken++;
    const payload: StoredHelpContent = {
      UPDT_DT_TM: new Date().toISOString(),
      sections
    };
    const dmInfo = this.customService.emptyDmInfo;
    dmInfo.infoDomain = DMINFO_DOMAIN;
    dmInfo.infoName = CONTENT_NAME;
    dmInfo.infoDomainId = 0;
    dmInfo.infoLongText = JSON.stringify(payload);

    this.customService.executeDmInfoAction('saveHelpContent', 'w', [dmInfo], () => {
      this.mPage.putLog('Help content saved');
    });
    this._storedSections.set(sections);
    this._loaded.set(true);
  }

  isShippedId(id: string): boolean {
    return HELP_SECTIONS.some(s => s.id === id);
  }

  defaultFor(id: string): EditableHelpSection | null {
    const shipped = HELP_SECTIONS.find(s => s.id === id);
    return shipped ? toEditableSection(shipped) : null;
  }

  getCachedImage(imageId: number): StoredHelpImage | undefined {
    return this.images.get(imageId);
  }

  loadImage(imageId: number, cb: (img: StoredHelpImage | null) => void): void {
    const cached = this.images.get(imageId);
    if (cached) { cb(cached); return; }

    const dmInfo = this.customService.emptyDmInfo;
    dmInfo.infoDomain = DMINFO_DOMAIN;
    dmInfo.infoName = IMAGE_NAME;
    dmInfo.infoDomainId = imageId;

    this.customService.executeDmInfoAction(`loadHelpImage${imageId}`, 'r', [dmInfo], () => {
      try {
        const result = this.customService.get(`loadHelpImage${imageId}`);
        const longText = readLongText(result);
        if (longText) {
          const img = JSON.parse(longText) as StoredHelpImage;
          this.images.set(imageId, img);
          cb(img);
          return;
        }
      } catch {
        this.mPage.putLog(`Help image ${imageId} unreadable`);
      }
      cb(null);
    });
  }

  saveImage(image: StoredHelpImage, cb: (imageId: number) => void): void {
    const imageId = Date.now();
    const dmInfo = this.customService.emptyDmInfo;
    dmInfo.infoDomain = DMINFO_DOMAIN;
    dmInfo.infoName = IMAGE_NAME;
    dmInfo.infoDomainId = imageId;
    dmInfo.infoLongText = JSON.stringify(image);

    this.customService.executeDmInfoAction(`saveHelpImage${imageId}`, 'w', [dmInfo], () => {
      this.mPage.putLog(`Help image ${imageId} saved`);
    });
    this.images.set(imageId, image);
    cb(imageId);
  }
}
