// src/app/content/view-help.content.ts
//
// Content for the "About this view" help modal. Pure data — the ViewHelp
// component renders whatever is here, so adding a section, item, screenshot,
// or animation is a content-only change. `technical` lines are aimed at
// administrators and name the Cerner source; `description` text is written
// for clinical users.

export interface HelpMedia {
  type: 'image' | 'gif';
  src: string;
  caption?: string;
}

export interface HelpItem {
  term: string;
  description: string;
  technical?: string;
}

export interface HelpSection {
  id: string;
  title: string;
  body?: string[];
  items?: HelpItem[];
  media?: HelpMedia[];
}

